<?php
require_once dirname(__DIR__) . '/app/helpers.php';
require_once dirname(__DIR__) . '/app/Services/BankingService.php';
require_auth();
$db=Database::connection();$user=auth_user();$service=new BankingService($db);
$stmt=$db->prepare('SELECT a.id,a.account_number,at.name AS type,at.currency FROM accounts a JOIN account_types at ON at.id=a.account_type_id WHERE a.user_id=? ORDER BY a.id');$stmt->execute([$user['id']]);$accounts=$stmt->fetchAll();
$accountId=(int)($_GET['account']??($accounts[0]['id']??0));$valid=array_map('intval',array_column($accounts,'id'));if(!in_array($accountId,$valid,true))$accountId=(int)($accounts[0]['id']??0);$rows=$accountId?$service->transactionsForAccount($accountId,100):[];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Transactions - <?=e(APP_NAME)?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="/commserve/public/assets/css/app.css" rel="stylesheet"></head><body><nav class="navbar bg-white border-bottom"><div class="container-fluid"><a class="navbar-brand fw-bold" href="/commserve/public/dashboard.php">CommServe <span class="badge text-bg-warning">DEMO</span></a><a class="btn btn-outline-secondary btn-sm" href="/commserve/public/dashboard.php">Dashboard</a></div></nav><main class="container-fluid p-4"><div class="d-flex flex-wrap justify-content-between align-items-center mb-4"><div><h2 class="fw-bold">Transactions</h2><p class="text-muted mb-0">Ledger-backed simulated account activity.</p></div><form><select class="form-select" name="account" onchange="this.form.submit()"><?php foreach($accounts as $a): ?><option value="<?=e((string)$a['id'])?>" <?=$accountId===(int)$a['id']?'selected':''?>><?=e($a['type'])?> · <?=e($a['account_number'])?></option><?php endforeach; ?></select></form></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>Date</th><th>Reference</th><th>Type</th><th>Description</th><th>Direction</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="text-center text-muted py-5">No transactions found.</td></tr><?php else:foreach($rows as $row):?><tr><td><?=e($row['created_at'])?></td><td class="small"><a href="/commserve/public/transaction.php?ref=<?=urlencode($row['reference'])?>"><?=e($row['reference'])?></a></td><td><?=e(ucfirst($row['type']))?></td><td><?=e($row['description'])?></td><td><span class="badge <?=$row['entry_type']==='credit'?'text-bg-success':'text-bg-danger'?>"><?=e(ucfirst($row['entry_type']))?></span></td><td class="fw-semibold">₦<?=number_format((float)$row['amount'],2)?></td><td><span class="badge text-bg-<?=in_array($row['status'],['completed'],true)?'success':($row['status']==='failed'?'danger':'warning')?>"><?=e(ucfirst($row['status']))?></span></td></tr><?php endforeach;endif;?></tbody></table></div></div></main></body></html>
